 sortAisRisk:()=>{renderPanel()},sortAisRange:()=>{$('#aisList').innerHTML=aisList([1,0,2,3]);$$('#drawer .segment button').forEach((b,i)=>b.classList.toggle('selected',i===1))},
 allTargets:()=>openPanel('ais'),showTarget:()=>{chartContext();state.following=false;state.zoom=1.35;state.panX=state.target===0?-135:0;syncChart();$('#ais-'+state.target)?.classList.add('selected');toast('Selected vessel highlighted on chart')},
