 toggleAis:()=>{state.ais=!state.ais;syncChart();renderPanel()},toggleDepths:()=>{state.depths=!state.depths;syncChart();renderPanel()},toggleContours:()=>{state.contours=!state.contours;syncChart();renderPanel()},toggleCorridor:()=>{state.corridor=!state.corridor;syncChart();renderPanel()},toggleWind:()=>{state.wind=!state.wind;syncChart();renderPanel()},toggleRadar:()=>{state.radar=!state.radar;syncChart();renderPanel()},
