 confirmControl:()=>{state.apEnabled=true;closeModal();syncStatus();renderPanel();toast('Preview controls enabled')},apTimeout:()=>{state.apTimeout=!state.apTimeout;renderPanel()},
 gpsLoss:()=>{state.gpsLost=!state.gpsLost;if(!state.gpsLost&&state.critical==='GPS signal lost')state.critical=null;state.acknowledged=false;syncStatus();renderPanel()},batteryStale:()=>{state.batteryStale=!state.batteryStale;syncStatus();renderPanel();if(state.view==='energy')renderView()},
 acknowledgeCritical:()=>{state.acknowledged=true;syncStatus();toast('Acknowledged. Alert remains until its cause is resolved.')},
 showHealth:()=>openPanel('health'),showAutopilot:()=>openPanel('autopilot'),showLayers:()=>openPanel('layers'),showRail:()=>openPanel('rail'),showRadar:()=>fullView('radar'),
 saveVessel:()=>{const name=$('#vesselName').value.trim(),draft=+$('#vesselDraft').value,safety=+$('#vesselSafety').value,capacity=+$('#vesselCapacity').value,reserve=+$('#vesselReserve').value;if(!name||draft<=0||safety<draft||capacity<1||reserve<5||reserve>90)return toast('Enter a name, safety depth ≥ draft, capacity ≥ 1 and reserve 5–90%.');Object.assign(state,{vessel:name,draftDepth:draft,safetyDepth:safety,capacity,reserve});$('.vessel-name').innerHTML=esc(name.toUpperCase())+' <span class="dim">/</span>';syncChart();syncStatus();toast('Vessel profile saved for this session')},
